import numpy as np

def r(x):
    return 0.5 * float(x)

def R(y_orig, y_new):
    e_orig = abs(float(y_orig) - 1.0)
    e_new = abs(float(y_new) - 1.0)
    if e_orig <= 1e-15:
        return e_new <= 1e-15
    order = np.log(e_orig / max(e_new, 1e-30)) / np.log(2.0)
    return abs(order - 2.0) <= 0.2
